package com.novelle.novelle.config;
import com.novelle.novelle.entity.*; import com.novelle.novelle.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner;
import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component; import java.time.LocalDateTime; import java.util.UUID;
/** Creates the admin account and (optionally) clearly-marked DEMO content on first run. Demo authors use @demo.novelle emails and a "Demo author" bio. */
@Component
public class DataSeeder implements CommandLineRunner {
  private final UserRepository users; private final PostRepository posts; private final PasswordEncoder enc;
  @Value("${novelle.seed-demo}") boolean seed; @Value("${novelle.admin.email}") String adminEmail; @Value("${novelle.admin.password}") String adminPw;
  public DataSeeder(UserRepository u,PostRepository p,PasswordEncoder e){ users=u; posts=p; enc=e; }
  User mk(String name,String email,String pw,String bio,String role){ User u=new User(); u.setFullName(name); u.setEmail(email); u.setPassword(enc.encode(pw)); u.setBio(bio); u.setRole(role); return users.save(u); }
  void post(User a,String t,String d,String c,String img,String body,int days){ Post p=new Post(); p.setAuthor(a); p.setTitle(t); p.setDescription(d); p.setCategory(c);
    p.setCoverImage("https://images.unsplash.com/"+img+"?auto=format&fit=crop&w=1200&q=70"); p.setContent(body); p.setCreatedAt(LocalDateTime.now().minusDays(days)); posts.save(p); }
  public void run(String... args){
    if(!users.existsByEmail(adminEmail.toLowerCase())) mk("Novelle Admin",adminEmail.toLowerCase(),adminPw,"Platform administrator.","ADMIN");
    if(!seed||posts.count()>0) return;
    String demo="Demo author. Sample content seeded for development.";
    User m=mk("Maya Rao","maya@demo.novelle",UUID.randomUUID().toString(),demo,"USER"),d=mk("Daniel Okafor","daniel@demo.novelle",UUID.randomUUID().toString(),demo,"USER"),s=mk("Sofia Lindqvist","sofia@demo.novelle",UUID.randomUUID().toString(),demo,"USER");
    post(m,"The Quiet Return of Local-First Software","Apps that keep your data on your device are making a comeback, and the reasons are practical.","Technology","photo-1518770660439-4636190af475","Cloud-only apps made sense when connections were the bottleneck. Today the bottleneck is trust, latency and outages.\n\n## What local-first means\n\nYour data lives on your device first and syncs when it can. Editing never waits on a server, and you keep working on a train, on a plane or during an outage.\n\nThe trade-off is conflict resolution, but modern sync tools have made that far more approachable than it was a decade ago.",1);
    post(d,"Writing Java Code Your Future Self Can Read","Naming, small methods and honest errors matter more than clever patterns.","Programming","photo-1461749280684-dccba630e2f6","Most code is read many more times than it is written. Optimise for the reader.\n\n## Three habits\n\nName things for what they mean in the domain, not for how they are stored. Keep methods short enough to describe in a sentence. Throw exceptions that tell the caller what to fix.\n\nNone of this is glamorous, but it is what keeps a codebase pleasant after two years.",2);
    post(s,"How to Ask for the Feedback Nobody Offers","Specific questions get specific answers. Here is how to ask better ones.","Career","photo-1519389950473-47ba0277781c","Asking 'any feedback?' invites polite silence. Ask about one decision instead: what would you have done differently in the second half of that meeting?\n\nPick someone who watched you work, ask within a few days, and say thank you without defending yourself.",3);
    post(m,"Learning in Public: A Slower Way to Get Better","Sharing half-finished work teaches more than waiting until it is perfect.","Education","photo-1522202176988-66273c2fd55f","Publishing notes while you learn forces you to explain ideas clearly, and readers will correct what you misunderstood.\n\nStart small: one paragraph a week about something that confused you. In a year you will have a record of real progress.",4);
    post(d,"What Language Models Are Actually Good At","They are strong at drafting and transforming text, and weaker at facts they cannot check.","Artificial Intelligence","photo-1485827404703-89b55fcc595e","Language models shine when the task is to reshape text: summarise, translate, restructure, suggest alternatives.\n\n## Where to be careful\n\nTreat factual claims as leads to verify. Give the model the source material and ask it to work from that, rather than from memory.",5);
    post(s,"A Desk, a Notebook, and Two Hours of Silence","A small morning ritual that made deep work possible again.","Lifestyle","photo-1499750310107-5fef28a66643","I stopped trying to find more time and started protecting two hours. Phone in another room, one notebook, one task.\n\nThe first week felt strange. By the third, those two hours produced more than the rest of my day combined.",6);
    post(m,"Why Your REST API Needs Boring Error Messages","Predictable status codes and plain messages save every client developer hours.","Programming","photo-1498050108023-c5249f4df085","Return 400 for bad input, 401 when the caller is not logged in, 403 when they are not allowed, and 404 when something is missing.\n\nPair each with a short message that says what to change. Boring errors are kind errors.",7);
    post(d,"Prompting Is Mostly Editing","Good results come from revising your instructions, not finding magic words.","Artificial Intelligence","photo-1516321318423-f06f85e504b3","Treat your first prompt as a draft. Read the output, notice what is missing, and add that context to the next attempt.\n\nExamples of the format you want beat adjectives every time.",8);
  }
}
